                    elementPosition.width +
                    "px; height:" +
                    elementPosition.height +
                    "px; top:" +
                    elementPosition.top +
                    "px;left: " +
                    elementPosition.left +
                    "px;";
                overlayLayer.style.cssText = styleText;
