                hintDot.className = "introjs-hint-dot";
                var hintPulse = document.createElement("div");
                hintPulse.className = "introjs-hint-pulse";

                hint.appendChild(hintDot);
                hint.appendChild(hintPulse);
                hint.setAttribute("data-step", i);

